export function buscarAlimentos(termo: string): AlimentoCompleto[] {
  const custom = carregarAlimentosCustom()
  const todos = [...custom, ...bancoAlimentos]
  const q = termo.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  return todos.filter(a =>
    a.nome.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(q)
  )
}

export function encontrarSubstitutos(alimento: AlimentoCompleto, limite = 5): AlimentoCompleto[] {
  if (!alimento.kcal || !alimento.gramas) return []
  const custom = carregarAlimentosCustom()
  const todos = [...custom, ...bancoAlimentos]
  const kcalAlvo = alimento.kcal / alimento.gramas
  return todos
    .filter(a => a.id !== alimento.id && a.kcal && Math.abs((a.kcal / a.gramas) - kcalAlvo) < 1.5)
    .sort((a, b) => Math.abs((b.kcal! / b.gramas) - kcalAlvo) - Math.abs((a.kcal! / a.gramas) - kcalAlvo))
    .slice(0, limite)
}

// ===== MEDIDAS CASEIRAS CUSTOMIZADAS =====

export interface MedidaCaseiraCustom {
  id: string
  alimentoId: string
  rotulo: string
  gramas: number
}

const MEDIDAS_STORAGE = "nutricare_medidas_custom"

function isBrowser(): boolean {
  return typeof window !== "undefined"
}

function isCloud(): boolean {
  try { return !!(process.env.NEXT_PUBLIC_SUPABASE_URL && process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY) }
  catch { return false }
}

async function cloudFetch(url: string, opts?: RequestInit): Promise<boolean> {
  try { const res = await fetch(url, opts); return res.ok } catch { return false }
}

export function carregarMedidasCustom(alimentoId: string): MedidaCaseiraCustom[] {
  if (!isBrowser()) return []
  try {
    const raw = localStorage.getItem(MEDIDAS_STORAGE)
    if (!raw) return []
    const todas: MedidaCaseiraCustom[] = JSON.parse(raw)
    return todas.filter(m => m.alimentoId === alimentoId)
  } catch {
    return []
  }
}

export function carregarTodasMedidasCustom(): MedidaCaseiraCustom[] {
  if (!isBrowser()) return []
  try {
    const raw = localStorage.getItem(MEDIDAS_STORAGE)
    if (!raw) return []
    return JSON.parse(raw)
  } catch {
    return []
  }
}

export async function criarMedidaCustom(alimentoId: string, rotulo: string, gramas: number): Promise<MedidaCaseiraCustom> {
  const nova: MedidaCaseiraCustom = {
    id: `mc_${Date.now()}_${Math.random().toString(36).slice(2, 5)}`,
    alimentoId,
    rotulo: rotulo.trim(),
    gramas,
  }
  const todas = carregarTodasMedidasCustom()
  todas.push(nova)
  localStorage.setItem(MEDIDAS_STORAGE, JSON.stringify(todas))
  if (isCloud()) {
    await cloudFetch("/api/medidas", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(nova) })
  }
  return nova
}

export async function removerMedidaCustom(id: string): Promise<void> {
  const todas = carregarTodasMedidasCustom()
  localStorage.setItem(MEDIDAS_STORAGE, JSON.stringify(todas.filter(m => m.id !== id)))
  if (isCloud()) {
    await cloudFetch(`/api/medidas?id=${id}`, { method: "DELETE" })
  }
}

// ===== MEDIDAS CASEIRAS DISPONÍVEIS =====

export interface MedidaDisponivel {
  rotulo: string
  gramas: number
  custom?: boolean
}

export function medidasDisponiveis(alim: Pick<AlimentoCompleto, "id" | "gramas" | "kcal" | "medidaCaseira">): MedidaDisponivel[] {
  const custom = carregarMedidasCustom(alim.id)
  const b = alim.gramas
  const k = alim.kcal ?? 0
  const densidade = k > 0 ? Math.min(1.5, Math.max(0.3, k / 200)) : 0.8
  const est = (ml: number) => Math.round(ml * densidade)
  const medidas: MedidaDisponivel[] = []
  const m = alim.medidaCaseira

  if (m && m.includes(";")) {
    for (const p of m.split(";")) {
      const match = p.match(/(.+?)\s*=\s*([\d.]+)\s*g\s*/)
      if (match) medidas.push({ rotulo: match[1].trim().replace(/\s+/g, " "), gramas: parseFloat(match[2]) })
    }
  } else if (m && m !== `${b}g`) {
    const partes = m.match(/^([\d\/,.]+)?\s*(.+)/)
    if (partes) {
      const unidade = (partes[2] || m).trim()
      medidas.push({ rotulo: `1 ${unidade}`, gramas: b })
      medidas.push({ rotulo: `1/2 ${unidade}`, gramas: Math.round(b / 2) })
      medidas.push({ rotulo: `2 ${unidade}`, gramas: b * 2 })
    }
  }

  medidas.push({ rotulo: `${b}g (padrão)`, gramas: b })
  medidas.push({ rotulo: `Colher de café`, gramas: Math.max(1, est(2)) })
  medidas.push({ rotulo: `Colher de chá`, gramas: Math.max(1, est(5)) })
  medidas.push({ rotulo: `Colher de sopa`, gramas: Math.max(1, est(15)) })
  medidas.push({ rotulo: `Colher de servir`, gramas: Math.max(1, est(30)) })
  medidas.push({ rotulo: `Xícara de chá (200mL)`, gramas: Math.max(1, est(200)) })
  medidas.push({ rotulo: `Copo americano (200mL)`, gramas: Math.max(1, est(200)) })
  medidas.push({ rotulo: `Unidade média`, gramas: b })
  medidas.push({ rotulo: `Fatia média`, gramas: Math.round(b * 0.6) })

  for (const c of custom) medidas.push({ rotulo: c.rotulo, gramas: c.gramas, custom: true })

  const vistos = new Set<number>()
  return medidas.filter(m => { if (vistos.has(m.gramas)) return false; vistos.add(m.gramas); return true })
}

export function rotuloMedidaPorGramas(gramas: number, medida: { rotulo: string; gramas: number }): string {
  if (!medida.gramas) return `${gramas}g`
  const qtd = Math.round((gramas / medida.gramas) * 10) / 10
  return qtd === 1 ? medida.rotulo : `${qtd}x ${medida.rotulo}`
}

// ===== ALIMENTOS PERSONALIZADOS =====

const ALIMENTOS_CUSTOM_STORAGE = "nutricare_alimentos_custom"

export function carregarAlimentosCustom(): AlimentoCompleto[] {
  if (!isBrowser()) return []
  try {
    const raw = localStorage.getItem(ALIMENTOS_CUSTOM_STORAGE)
    if (!raw) return []
    return JSON.parse(raw)
  } catch {
    return []
  }
}

export function salvarAlimentoCustom(alimento: AlimentoCompleto): void {
  if (!isBrowser()) return
  const todos = carregarAlimentosCustom()
  const existentes = todos.filter(a => a.id !== alimento.id)
  existentes.push(alimento)
  localStorage.setItem(ALIMENTOS_CUSTOM_STORAGE, JSON.stringify(existentes))
}

export function removerAlimentoCustom(id: string): void {
  if (!isBrowser()) return
  const todos = carregarAlimentosCustom()
  localStorage.setItem(ALIMENTOS_CUSTOM_STORAGE, JSON.stringify(todos.filter(a => a.id !== id)))
}

export function buscarAlimentosComCustom(termo: string): AlimentoCompleto[] {
  const custom = carregarAlimentosCustom()
  const todos = [...custom, ...bancoAlimentos]
  const q = termo.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  return todos.filter(a =>
    a.nome.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(q)
  )
}

